const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
const width = canvas.width;
const height = canvas.height;

const scoreBoard = document.getElementById('scoreBoard');
const winnerDisplay = document.getElementById('winnerDisplay');

const paddleWidth = 15;
const paddleHeight = 120;
const paddleSpeed = 40;
const winningScore = 5;

const paddleColor = '#03a9f4';
const ballColor = '#ff3d00';

let gameOver = false;

const leftPaddle = {
  x: 0,
  y: height / 2 - paddleHeight / 2,
  width: paddleWidth,
  height: paddleHeight,
  color: paddleColor
};

const rightPaddle = {
  x: width - paddleWidth,
  y: height / 2 - paddleHeight / 2,
  width: paddleWidth,
  height: paddleHeight,
  color: paddleColor
};

let ball = {
  x: width / 2,
  y: height / 2,
  radius: 12,
  speed: 5,
  dx: 1,
  dy: 1,
  color: ballColor
};

let score = {
  left: 0,
  right: 0
};

function resetBall() {
  ball.x = width / 2;
  ball.y = height / 2;
  ball.speed = 5;
  ball.dx = Math.random() < 0.5 ? -1 : 1;
  ball.dy = Math.random() < 0.5 ? -1 : 1;
}

function updateScoreBoard() {
  scoreBoard.textContent = `Player 1: ${score.left} | Player 2: ${score.right}`;
}

function declareWinner(player) {
  gameOver = true;
  winnerDisplay.textContent = `${player} Wins! 🎉`;
}

function drawPaddle(paddle) {
  ctx.fillStyle = paddle.color;
  ctx.fillRect(paddle.x, paddle.y, paddle.width, paddle.height);
}

function drawBall() {
  ctx.beginPath();
  ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);
  ctx.fillStyle = ball.color;
  ctx.fill();
  ctx.closePath();
}

function clearCanvas() {
  ctx.fillStyle = '#111';
  ctx.fillRect(0, 0, width, height);
}

function moveBall() {
  ball.x += ball.speed * ball.dx;
  ball.y += ball.speed * ball.dy;
}

function detectCollisions() {
  if (ball.y - ball.radius <= 0 || ball.y + ball.radius >= height) {
    ball.dy *= -1;
  }

  if (
    ball.x - ball.radius <= leftPaddle.x + leftPaddle.width &&
    ball.y >= leftPaddle.y &&
    ball.y <= leftPaddle.y + leftPaddle.height
  ) {
    ball.dx *= -1;
    ball.speed += 0.5;
  }

  if (
    ball.x + ball.radius >= rightPaddle.x &&
    ball.y >= rightPaddle.y &&
    ball.y <= rightPaddle.y + rightPaddle.height
  ) {
    ball.dx *= -1;
    ball.speed += 0.5;
  }

  if (ball.x + ball.radius < 0) {
    score.right += 1;
    updateScoreBoard();
    checkGameOver();
    resetBall();
  }

  if (ball.x - ball.radius > width) {
    score.left += 1;
    updateScoreBoard();
    checkGameOver();
    resetBall();
  }
}

function checkGameOver() {
  if (score.left >= winningScore) {
    declareWinner('Player 1');
  } else if (score.right >= winningScore) {
    declareWinner('Player 2');
  }
}

function gameLoop() {
  if (gameOver) return;

  clearCanvas();
  drawPaddle(leftPaddle);
  drawPaddle(rightPaddle);
  moveBall();
  drawBall();
  detectCollisions();
  requestAnimationFrame(gameLoop);
}

window.addEventListener('keydown', (e) => {
  if (gameOver) return;

  switch (e.key) {
    case 'w':
      leftPaddle.y = Math.max(0, leftPaddle.y - paddleSpeed);
      break;
    case 's':
      leftPaddle.y = Math.min(height - paddleHeight, leftPaddle.y + paddleSpeed);
      break;
    case 'ArrowUp':
      rightPaddle.y = Math.max(0, rightPaddle.y - paddleSpeed);
      break;
    case 'ArrowDown':
      rightPaddle.y = Math.min(height - paddleHeight, rightPaddle.y + paddleSpeed);
      break;
  }
});

document.getElementById('resetBtn').addEventListener('click', () => {
  score.left = 0;
  score.right = 0;
  updateScoreBoard();
  winnerDisplay.textContent = '';
  gameOver = false;
  resetBall();
  gameLoop();
});

updateScoreBoard();
resetBall();
gameLoop();
